// Same output as JSON.stringify(value, null, 2), but iterative: a patch can
// build a result far deeper than the input limit, beyond the native recursion.
function stringifyPretty(value) {
  const out = [];
  const stack = [{ value, depth: 0 }];
  while (stack.length > 0) {
    const item = stack.pop();
    if (typeof item === 'string') {
      out.push(item);
      continue;
    }
    const { value: v, depth } = item;
    if (v === null || typeof v !== 'object') {
      out.push(JSON.stringify(v));
      continue;
    }
    const isArr = Array.isArray(v);
    const keys = isArr ? null : Object.keys(v);
    const count = isArr ? v.length : keys.length;
    const [openCh, closeCh] = isArr ? ['[', ']'] : ['{', '}'];
    if (count === 0) {
      out.push(openCh + closeCh);
      continue;
    }
    const indent = `\n${'  '.repeat(depth + 1)}`;
    out.push(openCh);
    stack.push(`\n${'  '.repeat(depth)}${closeCh}`);
    for (let i = count - 1; i >= 0; i--) {
      stack.push({ value: isArr ? v[i] : v[keys[i]], depth: depth + 1 });
      stack.push(`${i > 0 ? ',' : ''}${indent}${isArr ? '' : `${JSON.stringify(keys[i])}: `}`);
    }
  }
  return out.join('');
}

