import { test } from 'node:test';
import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';

const CLI = fileURLToPath(new URL('../jsonpatch-cli.mjs', import.meta.url));

function runWithStdinDoc(patch, doc) {
  const r = spawnSync(process.execPath, [CLI, '-'], { input: '' });
  void r;
  return spawnSync(process.execPath, ['--input-type=module', '-e', `
    import { writeFileSync, mkdtempSync } from 'node:fs';
    import { tmpdir } from 'node:os';
    import { join } from 'node:path';
    const dir = mkdtempSync(join(tmpdir(), 'jp-out-'));
    const p = join(dir, 'p.json');
    writeFileSync(p, process.argv[1]);
    process.argv[1] = p;
