  if (!stdinIsReadable()) return Promise.reject(readFailure('stdin', 'cannot read'));
  return new Promise((resolve, reject) => {
    const stdin = process.stdin;
    const chunks = [];
    let total = 0;
    const finish = (err) => {
      stdin.removeAllListeners('data');
      stdin.removeAllListeners('end');
      stdin.destroy();
      if (err) reject(err);
      else resolve(Buffer.concat(chunks));
    };
    stdin.on('data', (chunk) => {
      total += chunk.length;
      if (total > MAX_BYTES) finish(readFailure('stdin', 'too large'));
      else chunks.push(chunk);
    });
    stdin.on('end', () => finish(null));
    stdin.on('error', () => finish(readFailure('stdin', 'cannot read')));
  });
}

function jsonDepth(value) {
  let max = 0;
  const stack = [[value, 0]];
  while (stack.length > 0) {
    const [v, depth] = stack.pop();
    if (v === null || typeof v !== 'object') {
      max = Math.max(max, depth);
      continue;
    }
    max = Math.max(max, depth + 1);
    for (const child of Array.isArray(v) ? v : Object.values(v)) stack.push([child, depth + 1]);
  }
  return max;
}

// Writes JSON.stringify(value, null, 2) through `emit` in chunks, iteratively:
// a patch can build a result far deeper and larger than the native one handles.
function writePretty(value, emit) {
  let out = '';
  const push = (text) => {
    out += text;
    if (out.length >= OUTPUT_CHUNK) {
      emit(out);
      out = '';
    }
  };
  const newline = (depth) => `\n${'  '.repeat(depth)}`;
  // Each frame is a container being written and the index of its next entry.
  const frames = [];
  const writeValue = (v, depth) => {
    if (v === null || typeof v !== 'object') {
      push(JSON.stringify(v));
      return;
    }
    const isArr = Array.isArray(v);
    const keys = isArr ? null : Object.keys(v);
    const count = isArr ? v.length : keys.length;
    if (count === 0) {
      push(isArr ? '[]' : '{}');
      return;
    }
    push(isArr ? '[' : '{');
    frames.push({ v, isArr, keys, count, depth, next: 0 });
  };
  writeValue(value, 0);
  while (frames.length > 0) {
    const frame = frames[frames.length - 1];
    const { v, isArr, keys, count, depth } = frame;
    if (frame.next === count) {
      frames.pop();
      push(`${newline(depth)}${isArr ? ']' : '}'}`);
      continue;
    }
    const i = frame.next++;
    push(`${i > 0 ? ',' : ''}${newline(depth + 1)}`);
    if (isArr) {
      writeValue(v[i], depth + 1);
    } else {
      push(`${JSON.stringify(keys[i])}: `);
      writeValue(v[keys[i]], depth + 1);
    }
  }
  emit(out);
}

const inputFailure = (name, reason) => new CliError(`Error: ${name}: ${reason}`, 3);

async function loadInput(arg) {
  const name = arg === '-' ? 'stdin' : arg;
  const bytes = arg === '-' ? await readStdin() : await readFileInput(arg);
  let text;
  try {
    text = new TextDecoder('utf-8', { fatal: true }).decode(bytes);
  } catch {
    throw inputFailure(name, 'invalid UTF-8');
  }
  let value;
  try {
    value = JSON.parse(text);
  } catch {
    throw inputFailure(name, 'invalid JSON');
  }
  if (jsonDepth(value) > MAX_DEPTH) throw inputFailure(name, 'too deep');
  return value;
}

async function main(args) {
  if (args.length < 1 || args.length > 2) throw new CliError(USAGE, 2);
  const [patchArg, docArg = '-'] = args;
  if (patchArg === '-' && docArg === '-') throw new CliError(USAGE, 2);
  const patch = await loadInput(patchArg);
  const doc = await loadInput(docArg);
  let result;
  try {
    result = applyPatch(doc, patch);
  } catch (err) {
    if (err instanceof PatchError) throw new CliError(`Error: ${err.message}`, 4);
    throw err;
  }
  writePretty(result, (chunk) => process.stdout.write(chunk));
  process.stdout.write('\n');
}

try {
  await main(process.argv.slice(2));
} catch (err) {
  // Anything unexpected still ends as one plain line rather than a stack trace.
  const cliErr = err instanceof CliError ? err : new CliError(`Error: ${err?.message ?? err}`, 1);
  process.stderr.write(`${cliErr.message}\n`);
  process.exitCode = cliErr.code;
}

import { describe, test, before, after } from 'node:test';
import assert from 'node:assert/strict';
import { expectOk, makeTmpDir, removeTmpDir, run, writeIn } from './helpers/cli-runner.mjs';

describe('CLI output formatting', () => {
  let dir;
  before(() => { dir = makeTmpDir(); });
  after(() => removeTmpDir(dir));

  test('output matches JSON.stringify(result, null, 2) for mixed values', () => {
    const doc = {
      s: 'a"\\\n é', n: [-0, 1.5, 1e21, -3], e: [], o: {}, z: null, t: true, f: false,
      '__proto__': { 'k"y': [[], [{}], [1, [2, { a: 'b' }]]] }, 10: 'ten', 2: 'two',
    };
    const p = writeIn(dir, 'mixed-p.json', '[]');
    const d = writeIn(dir, 'mixed-d.json', JSON.stringify(doc));
    const expected = JSON.stringify(JSON.parse(JSON.stringify(doc)), null, 2);
    expectOk(run([p, d]), `${expected}\n`);
  });

  test('scalar documents print like JSON.stringify', () => {
    const p = writeIn(dir, 'scalar-p.json', '[]');
    for (const text of ['"x"', '-0', '0.1', 'null', 'false', '[]', '{}']) {
      expectOk(run([p, '-'], { input: text }), `${JSON.stringify(JSON.parse(text), null, 2)}\n`);
    }
  });

  test('a valid patch that builds a result far deeper than 1000 levels still prints', () => {
    const depth = 999;
    const doc = JSON.parse(`${'{"a":'.repeat(depth - 1)}{"x":0}${'}'.repeat(depth - 1)}`);
    const leaf = `${'/a'.repeat(depth - 1)}/x`;
    const patch = [];
    let path = leaf;
    for (let i = 0; i < 10; i++) {
      patch.push({ op: 'copy', from: '', path });
      path = `${path}${'/a'.repeat(depth - 1)}/x`;
    }
    const p = writeIn(dir, 'deep-p.json', JSON.stringify(patch));
    const d = writeIn(dir, 'deep-d.json', JSON.stringify(doc));
    const res = run([p, d]);
    assert.equal(res.stderr, '');
    assert.equal(res.status, 0);
    assert.ok(res.stdout.endsWith('}\n'));
    assert.ok(res.stdout.split('\n').length > 10 * depth);
  });
});

